INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1018605-me315', 'stk-user5643', 'ME 315', 'info', '{"desc": "من اسوا كورسات التخصص 😦\n\nلا كتاب واضح … و لا سيلبوس واضح … ماتدري ايش المطلوب منك في الكورس … وغالبا الداتره الي يدرسون الكورس مو ذاك الزود …\n\nكورس حطمني صراحه\n\nاتوقع المفروض يكون اوبن بوك هالكورس …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/2", "user": "user5643", "ts": 1333541478000, "tid": 120745, "pn": 2}}', 1333541478000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162521-me315', 'stk-user5430', 'ME 315', 'info', '{"desc": "بالنسبة لي - مادة ممتعه -\n\nالمادة تتكلم بالتفصيل عن ثلاثه أجزاء لانتقال الحرارة :\nconduction\nconvection\nradiation\n\nو تدرسون تطبيقاتها في المصانع مثل heat exchanger\nكتابها مش ولا بد … لكن ميزتها لها مانيوال سلوشن ❤️ 😆\n\nانصح تنزل هالكورس عند محمد عنتر اذا هو منزلها 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/3", "user": "user5430", "ts": 1357944909000, "tid": 120745, "pn": 3}}', 1357944909000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162582-me315', 'stk-aziz_saleem', 'ME 315', 'info', '{"desc": "121 - مع د. فهد السليمان\n\nجودة المقرر بشكل عام:\nالمقرر حلو في بعض اجزائه و غثيث جدا في أخرى , يبغالك تراجعه من فترة لأخرى , لا تأجل شغله أبدا لأنه ممكن يلخبطك في الأخير\n\nالمواضيع التي يغطيها المقرر:\nيغطي المواضيع التاليه : heat transfer by ( conduction - convection- radiation ) , heat exchanger,\nالكوندكشن :مش مره صعب بس فيه بارت الفنز في آخر الشابتر يبغالها دفرة شوي ,\nالكونفكشن : مش صعب برضه بس ممكن طرق الحل تلخبطك شوي لأنه في أكثر من معادله و حالة للحل , تحل أسئلة الهوم وورك و تضبط أمورك ,\nالرادياشن : آخر شابترين و مسائلهم قليله , أحسها عاديه صراحه ,\nالهيت اكسشانجر : أهم بارت في الكورس ذا و لازم تخرج من الكورس و انت فاااااهمه مضبوط , يمكن يضايق البعض وقت الحل بس مع البراكتس و حل أسئلة الهوموورك راح تصير معروفه لك و راح تفهم كيف تجي تركاتها ,\n\nالكتاب المستخدم للمقرر:\n\nما كنت أذاكر منه , كنت بس أراجع الأمثله اللي فيه , و كنت افتح ملفات الوورد اللي بال(open courseware) و كانت كافية بالنسبة لي ,\n\nملاحظات :\n-الهوم وورك عليه 10 % و الدرجة في يدك لا تضيعها , السيلوشن مانيول موجود , لا تتكاسل و ما تحلها لأنها تقريبا أسبوعيا تتسلم ,\n\n-الكويزات مع دكتور فهد كان عليها 12 % و ما أعطانا إلا 3 كويزات بس , فلو أخذتها معاه ركز فيها و جيب درجات حلوه لانه ما راح يعطيكم ميك اب عليها ,\n\n- الكورس ممكن تستمتع فيه و تعتمد على نفسك لو ما فهمت من الدكتور , يبغالك تحل مسائل و تتعود على كتابة القوانين لأنها في الغالب تتشابه , قد ما يقولولك الكورس سيء و كدا انت ادخل و انت مطنش الاحباطات النفسيه دي و شد حيلك ,\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/4", "user": "aziz_saleem", "ts": 1357957826000, "tid": 120745, "pn": 4}}', 1357957826000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1231786-me315', 'stk-abu_hamad', 'ME 315', 'info', '{"desc": "من اسهل الكورسات بالنسبه لي ,اشوفه اسهل من الثيرمو والفلويد ,مافيه اي تعقيد في المسائل اللي تجيك في الاختبارات ,بس عيب الكورس ان الكتاب سيء لفهم الكونسبت وجيد في الامثله اللي يحتويها والاسئله نهايه كل شابتر ,لذا ذاكر الكونسبت من سلايدات دكتورك ومن open courseware,بعدها حل امثلة الكتاب واسئلة الهومورك, واللي تقدر عليه من اسئله اضافيه ,كذا بتكون امورك في السليم ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/5", "user": "Abu_Hamad", "ts": 1370346435000, "tid": 120745, "pn": 5}}', 1370346435000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1378196-me315', 'stk-user4626', 'ME 315', 'info', '{"desc": "بشكل عام الكورس يعتبر كورس متوسط لكنه يقلب صعب جدا بسبب سوء الكتاب المستخدم\nباختصار في اجزاء تتعلق بالmass ترانسفير هذه محذوفة و تلاقيها في وسط الكلام مما يسبب اللخبطة العظيمة\n\nنصحيتي في الكورس هذا انه الواحد يكتب نوت مع الدكتور و يركز مع الشرح لانه بيتعب كثير مع الكتاب\nو كمان اقدر اقول انه الهوموركات مالها اي علاقة بالمياجر او بالفاينل ، الهوموركات في وادي و الاختبارات في وادي\nالكورس فيه معلومات جدا مهمة بما يتعلق بالهيت اكسجينجر الي في مادة اللكتيف له لحلاله و الكورس جدا مفيد في سوق العمل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/8", "user": "user4626", "ts": 1402197705000, "tid": 120745, "pn": 8}}', 1402197705000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1468330-me315', 'stk-hamd00ni', 'ME 315', 'info', '{"desc": "^^^\n\nعندك سلايدات القحطاني لكنها غير مرتبه\n\nأنا أنصحك تفتح سلايدات القحطاني أو سلايدات دكتورك وتفتح الكتاب وتمشي وتحدد القوانين المهمه في الكتاب وبعدها تفتح الاقزامبلز وذاكر اللي تقدر عليه (يعني اللي تحس انه معقد اسحب عليه) وبعدها ذاكر الهوموورك\n\nبرضو أنصح انك تلخص القوانين المهمه واستخداماتها في ورقة خارجية\n\nولا تنسى انه من تشابتر ٦ وانت طالع نهاية التشابتر فيه جدول مهم جدا يلخص كووول القوانين اللي في التشابتر ويعطيك متى تستخدمها (يمديك تذاكر منه)\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/12", "user": "Hamd00ni", "ts": 1487114058000, "tid": 120745, "pn": 12}}', 1487114058000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527086-me315', 'stk-ahm2d1', 'ME 315', 'info', '{"desc": "جودة المقرر بشكل عام: سيء بسبب طول المنهج.\nالمواضيع التي يغطيها المقرر: اشياء كثير بس اهمها : Conduction & convection & Radiation & Heat Exchanger\n\nالكتاب المستخدم للمقرر: الكتاب يمشي الحال بس فيه اجزاء ماهي معنا فا ايام ما بتعرف هو معك في الكورس او لا.\n\nالأسئلة والأمثلة المستخدمة في المقرر: جيده بس بعض الاحيان بدل مايجيب لك سوال سهل ويخليك تفهم الاساسيات شوي شوي , يجيب لك سوال حتى دكاتره ما يحلونه.\n\nمدى فائدته في الناحية التطبيقية: الكورس واضح انه مهم بس ما عرفوا يتعاملون معه بسبب طول المنهج والقوانين الموجوده.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-heat-transfer/120745/13", "user": "Ahm2d1", "ts": 1607930633000, "tid": 120745, "pn": 13}}', 1607930633000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1224670-me315', 'stk-user2057', 'ME 315', 'info', '{"desc": "حسب ما اتذكر القحطاني هو الوحيد اللي كان يحط الاسئلة مختلفة عن باقي السكاشن (كومن).\n\nعموما نصيحتي لك ذاكر الاختبارات القديمة اللي هو بنفسه يحطها. وفيه اسئلة كانت عبارة عن اختر الاجابة الصحيحة كانت تجي نصاً تقريبا حدود 50 فقرة هو يوزعها ويجيب منها 4 او 5 فقرات اذا ما خانتني الذاكرة.\n\nعموما للامانة النوت حقه جييد وما يحتاج تفتح الكتاب الا في اخر تشابتر واللي كان عن الاشعاعات وانعكاساتها والله ناسي اسم التشابتر بالضبط", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me315/144760/3", "user": "user2057", "ts": 1369038703000, "tid": 144760, "pn": 3}}', 1369038703000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1225179-me315', 'stk-metallic', 'ME 315', 'info', '{"desc": "أظن الأخ VIP Master ماخذ الكورس من زمان ، أنا أخذت الكورس السمستر الماضي وكان الكورس كامل كومن (يشمل سكاشن القحطاني)، واحد أعرفه كان يدرس عنده وأنا كنت عند السليمان والاسئلة كانت وحدة…\nوالفاينل جانا سهل ، فلا تشيلون هم ياشباب … صحيح أنه كومبرهنسف بس أنك تقدر تغطيه كامل والمعادلات بتعطى لك في الاختبار مع الفيقورز … الشيء الوحيد اللي تحسفت أني ما ذاكرته الفينز مع أنها كانت من متيريل ميجر ون !\n\nهنا الفورمولا شيت اللي جتنا بفاينل السمستر اللي فات …\n\nhttps://www.dropbox.com/s/llpuud5plk25bbg/1.zip", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me315/144760/12", "user": "METALLIC", "ts": 1369108368000, "tid": 144760, "pn": 12}}', 1369108368000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429064-me315', 'stk-hello_world', 'ME 315', 'info', '{"desc": "يا حبايب والله المنهج طلع طويل و يبغاله أول شرح للقوانين بعدين نحل الأولد اكزامز …\nايش رأيكم نبدأ من بعد الميجر الأول و نذاكر كل تشابتر بوقته لأن كذا شغل سريع سريع و المنهج ثقيل\n.\n.\nأنا آسف إني قلت لكم نجتمع قبل ما أحضر بس و الله حضرت و طلع شغل جدددا كثير على إجتماع واحد\nإذا موافقين معاي إننا نجتمع بعد الميجر الأول و كل تشابتر بوقته يا ليت تحطون أرقام جوالاتكم أو ايميلاتكم عشان أتواصل معاكم و نرتب وقتنا\n\nالله يوفقكم أجمعين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/problem-solving-sessions-for-me-315/169922/10", "user": "Hello_World", "ts": 1442858858000, "tid": 169922, "pn": 10}}', 1442858858000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1019461-me315', 'stk-mechanical_boy', 'ME 315', 'info', '{"desc": "315 وماارداك ما 315 من اغثثثثثث كورسات الميكانكل من جد مادري وش يبي هالكورس تعقيد في تعقيد ولا حنا عارفين نذاكر من وين وبرضو مانعرف وش السكاشن المحذوفه في كل شابتر لانها ماهي موضحه في السيلابلس ودكتورنا بلكتشرين يطمر شابترين تلقاه طامر 11 ثم يرجع سته ثم سبعه يعني بصراحه احس اني ضااااااااااااااااااااااااااايع بالماده وصرت اطمح اني اعديها باي شي 😞\n\nلذلك حبيت اخذ رايكم الي يدرسها حاليا او سبق واخذها كيف تذاكرونها من اي مصدر خاصه ان كتاب الماده غثيث كله كلام في كلام وكيف تكون جاهز للمياجر والي عنده فكره عن السكاشن المحذوفه بكل شابتر مثلا اذا كانت موجوده عنده بالسيلابلس او كان متابع مع الدكتور وعارف وش الي مو مطلوب ياليت يعطينا خبر واكون له شاكر 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315/123974/1", "user": "Mechanical_Boy", "ts": 1333665339000, "tid": 123974, "pn": 1}}', 1333665339000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1172710-me315', 'stk-_004', 'ME 315', 'info', '{"desc": "هلا بك أخوي شوف هالهاند أوتس فادتني يوم خذيت الكورس\nhttp://opencourseware.kfupm.edu.sa/colleges/ces/me/me315/lectures.asp\nذاكرها و شيك على امثله الكتاب واسءله الهومورك وزد عليها كم سوال وامورك ان شاء الله تمام\nعلى العموم الكورس شوي غثيث وصراحه بالكتاب الحاله تبي تتعب ما مشاني بعد الله الا هالهاند اوتس تعطيك الزبده صح\nوبرضو عندي اولد اقزام بس فيها اللي محلول بزفعها هنا بدري\nبالتوفيق يا خلفهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me315/139441/2", "user": "_004", "ts": 1359471670000, "tid": 139441, "pn": 2}}', 1359471670000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1019475-me315', 'stk-user5216', 'ME 315', 'info', '{"desc": "هلا يالغالي\n\nشوف ياقلبي انا مااذاكر الا من النوت هذا\nhttp://opencourseware.kfupm.edu.sa/colleges/ces/me/me315/lectures.asp\n\nوهو عباره عن ملخص للكلام الفاضي الي بالكتاب ويشرح لك فيه السكاشن الي معك بس\n\nمثلا لو تروح لـ تشابتر 11 ( الي يحتوي على 9 سكاشن )\n\nتلاقيه في النوت حاطلك 11.1 الي 11.5 ( يعني هذا الي داخل معك فقط )\n\nراجع النوت + الامثلة المحلولة الي في الكتاب\n\nومالنا غير كذا والله يعدي هالكورس الغثيث على خير 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315/123974/2", "user": "user5216", "ts": 1333666628000, "tid": 123974, "pn": 2}}', 1333666628000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p97159-me315', 'stk-user30', 'ME 315', 'info', '{"desc": "السلام عليكم …\n\nاعتذر ابو دحيم ماكنت اعرف انه قاندي مو نزل الترم الجاي …\n\nلكن على كل حال … ماانصحك في شجاع …\n\nبن منصور كان لنا لقاء معاه امس في دورة فلوينت … قال لنا انه بيدرس الكورس استنادا على مبدأ\n\n“Learn by doing” ،، يعني راح يخلي الكورس يعتمد على الجانب العملي اكثر من النظري …\n\nوراح يسوي بروجكتات مع الطلاب ويروحون مصانع ويدرسون المادة عمليا وليس فقط نظريات\n\nوقوانين ومسائل ،،\n\nفإذا كنت تحب هذا النوع من التدريس ( طبعا اكيد فيها بروجكتات وكرررف) لكن ممتعه جدا وتفيد\n\nالطالب كثير … لأن الطالب ينسى الكلام النظري اذا ماطبقه عمليا …\n\nتحياتي ،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315/50490/5", "user": "user30", "ts": 1147078146000, "tid": 50490, "pn": 5}}', 1147078146000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p99939-me315', 'stk-user1290', 'ME 315', 'info', '{"desc": "طيب أخي عاشق الريم وبعد طريقة بن منصور صدقني مارح يفيدهم في الفاينل لأنه كومن\n\nصح انه مفيدة وممتعة اذا كان لكل مدرس اسئلة خاصة فيه\n\nنصيحتي لك\n\nبن منصور اتركه ولا يطرا لك بن منصوووور والله سئ للغاية في المعاملة\n\nوبالنسبة لغانديداسان الله يستر عليه بيروح الهند السمستر الجاي وعلى فكرة ترا قريداته مش ولابد\n\nواسلوبه يعتمد على التحفيظ ويجي ويحل الهوموركات كالمة لكم في الكلاس ماعليك الا انك تكتبها من جديد في ورقة\n\nاذا عنتر منزل المادة صدقني نزل معه تراه والله مصري وفاهم المادة وبيفهمك وفي الاخير يدف بالقريدات شوي وركز على كلمة شوي\n\nشجاع ترا يفمهك المادة زي عنتر ولكن يحسسك بأسلوبه انك غبي جدا واسئلته صعبة وفي الاخير مايعطي قريدات الا بالموت الحمر\n\nوالقحطاني ترا ماهوب فاهم المادة بنفسة لانه ماهو فاضي للمادة والتدريس لانه جالس يحب الترزز في مجلة الجامعة دائما واذا منت مصدقني رح عند مكتبه وشف ولك الحكم\n\nخذ عنتررررررررررررررررر واذا سكرت عليك الامور نزل المادة مع شجاع أقل شيء تخرج وانت فاهم الماة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315/50490/6", "user": "user1290", "ts": 1149445736000, "tid": 50490, "pn": 6}}', 1149445736000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p998447-me315', 'stk-ghetto', 'ME 315', 'srcP', '{"html": "للي ما عنده فكرة عن جدول المياجر المعد مسبقا للسمسترات في السنوات القادمة (بدا تطبيقه من سنة اتوقع) موجود في المرفقات<br><br>​<span data-fid=\"stk-f998447-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f998447-0": {"name": "Major Exam Schedule for Multisection Courses.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/c61ba49debecaf9a50af1c91c995ef1163fadd3a1e1b4ecc4b9939e0fcfb2b57"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-307-308/122133/18", "user": "ghetto", "ts": 1330703875000, "tid": 122133, "pn": 18}}', 1330703875000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1172070-me315', 'stk-user4760', 'ME 315', 'srcU', '{"html": "بالمرفقات يالغالي …<br><br>بالتوفيق 👍<br><br>​<span data-fid=\"stk-f1172070-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1172070-0": {"name": "ME315-122_Syllabus.pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me315-syllabus/139310/2", "user": "user4760", "ts": 1359400112000, "tid": 139310, "pn": 2}}', 1359400112000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1447336-me315', 'stk-user8699', 'ME 315', 'srcU', '{"html": "بالخطأ مكان الموضوع معلييييش<br>مدري كيف احذفه 🤪<br><br>​<span data-fid=\"stk-f1447336-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1447336-0": {"name": "Design project (152).pdf", "v": "data:application/pdf;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-project/173066/1", "user": "user8699", "ts": 1461434398000, "tid": 173066, "pn": 1}}', 1461434398000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1000784-me315', 'stk-user6991', 'ME 315', 'srcP', '{"html": "السلام عليكم ،،<br><br>هذا الميجر اعطانا اياه دكتورنا عنتر<br><br>الله ييسر عليكم<br><br>في أمان الله<br><br>​<span data-fid=\"stk-f1000784-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1000784-0": {"name": "old exam.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a19ff26326fe68d67ba7458f3b11695eac302ec627a4fa3c4c8464b8d4d0dbfd"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-315-old-first-major-exam/122361/1", "user": "user6991", "ts": 1330943833000, "tid": 122361, "pn": 1}}', 1330943833000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5430-me315', 'stk-user5430', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98179", "n": "Dr. Fahad Abdul-Aziz Al-Sulaiman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315 - ترم 121\nالتحضير : يوميآ , ويأخذ ليت بعد 😆\nطريقة الشرح : بالنسبة لي شرحه سيء , هو يحاول و يبذل كل اللي عنده ولكن توصيلة للمعلومة ضعيف\nالكويزات : اسئلة هومورك , وأحيانا يغير رقم بسيط < لاتضيعها 😆\nالمياجر: كومن - تصحيحه اتعب وأقول عسل 🤠\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: واضح , اللهجه لك عليهآ شويات\nإضافات :\n\nالدكتور هذا لا قالوآ لك دكتور قريد ❤️ 🤠\nحبيب , وابتسامته ما تغيب عن وجهه حتى لو كان في اقصى مراحل الزعل\nتحس روحه طيبه , ويبذل كل اللي عنده لجل يساعد الطلاب 🌹\nالافريج عنده B … أعتمد على نفسك بالفهم و ابشر بتصحيح وقريدآت 🤠\nنزل عنده وأنت أعمى < يعني اكثر من نزل عنده و انت مغمض 😁\n\nهالمشاركة لعيون حبيبنآ إهتم بدراستك ❤️ 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1163188-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fahad-abdul-aziz-al-sulaiman/98179/20", "user": "user5430", "ts": 1358029982000, "tid": 98179, "pn": 20}}]}', 1358029982000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-me315', 'stk-turky_al-dossary', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98179", "n": "Dr. Fahad Abdul-Aziz Al-Sulaiman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me-315 - 121\n\nالتحضير ::\n\nيحضر في البداية اول خمس دقايق ،، وبعدها تكون متاخر ،، كلاسي الساعة 7 ،، وصلت معه 9 تاخيرات وكم غياب ،، الله يستر من الدرجات لا تطير\n\nطريقة الشرح ::\n\nالمدرس احس ان فيه ربشه ،، والانجليزي تعبان عنده ،، لو يشرح عربي احسن له ،، يشرح من السلايدات قرايه المدرس مو ذاك الشرح ابد يعني لازم تعتمد على نفسك بشكل كبير ،،\n\nالكويزات ::\n\nقريبة من اسئلة الهومورك ،، وصعبة ،، الهومورك موجود حلة بس في اشياء ما تدري كيف يحلها بسبب شرح المدرس\n\nتصحيح الكويزات مو هو اللي يصحح اللي يصحح قريدر ،، وخسف في التصحيح\n\nالمياجر::\n\nتصحيحة في المياجر ،، من الآخر ،، بــــــطـــــل\n\nالفاينل ::\n\nالى الان ما ادري ارجع ان شاء الله واكتب وش يصير\n\nالقريد النهائي ::\n\nاذا انت واحد تعتمد على شرح المدرس وما يهمك التصحيح فاعطيه d\n\nاذا انت واحد تعتمد على نفسك ويهمك التصحيح فاعطيه a\n\nالصوت ::\nواضح\n\nاضافات ::\nالمدرس يعطي اوراق في المحاضرة ويخليك تحلها بس احس اني ما استفيد منها بس احسن من لا شيء\n\nالبروجيكت توه معطينا اياه وشكله كرف بس لي رجعة\n\nاي استفسار ،، انا حاضر على الخاص ❤️ 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1208862-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fahad-abdul-aziz-al-sulaiman/98179/24", "user": "Turky_Al-Dossary", "ts": 1365694427000, "tid": 98179, "pn": 24}}]}', 1365694427000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-voldy-me315', 'stk-voldy', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98188", "n": "Dr. P. Gandhidasan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 315 - 132\n\nالتحضير :\nآخر الكلاس برقم الآيدي. مسموح لك بغيابين خلال السمستر (حقت المياجر)\n\nطريقة الشرح :\nيشرح من نوتات كاتبها بخط يده قبل سبع سنوات (آخر مرة درس المادة)\nبرأيي شرحه سيء جدا يقعد أغلب الوقت يشرح الدريفيشن ويعطي هنت على الهومورك ونادرا ما يحل مسائل\n\nالكويزات :\nسهلة وشبية بأمثلة الكتاب أو الأسئلة الي يحلها\n\nالمياجر:\nكومون. لكن تصحيحه ظالم لأبعد الحدود واذا رحتله وناقشته اقل شيء تطلع ب 5 درجات (ولو انك تستحق اكثر لكن اذا صجيته يعطيك كم درجة) عنده سياسة ان الاجابة النهائية لازم صح ولا كل شيء سويته غلط\n\nالفاينلات :\nكومون. الله أعلم عن التصحيح لكن أظن خف يده لأني طلعت بقريد كويس\n\nالقريد النهائي:\nb+\n\nالصوت:\nواضح جدا\nلكن ما تفهم وش يقول ياكل حروف احيانا او يخترعله كلمات من راسه\n\nإضافات :\nالمدرس خلوق جدا ومتساعد لكن الشرح في وادي وهو في وادي\nأنا أغلب الدروس فهمتها من الهيلب سيشن حق عنتر (الأفضل من ناحية الشرح)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375382-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-p-gandhidasan/98188/23", "user": "Voldy", "ts": 1401635623000, "tid": 98188, "pn": 23}}]}', 1401635623000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dyaa94-me315', 'stk-dyaa94', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98188", "n": "Dr. P. Gandhidasan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "162 - ME315\n\nاخلاق…يحضر اول باول لك غيابين فري\n\nبالنسبه للمحاضره…بداية الكلاس يحل تمارين…شريح في الحل\n\nالنص الثاني يشرح عالسريع وماعجبتني طريقته…يفتح نوتاته اللي ماينفهم خطه فيها ويشرح عالسريع اهم شي يخلص المنهج…\n\nبس في حل التمارين ياخذ وقته ويشرح صح\n\nالتصحيح Mostly جيد في التصحيح…ميجر 2 شدد شوي بالتصحيح لان شاف الافرج اعلى…ميجر 1 والكوزات كان كريم بالتصحيح…\n\nالدرجات ينزلها اول باول في البلاكبورد…الا الفاينل والبروجكت سحب علينا ههههه…حط اللتر قريد في البورتل وماسمعنا منه بعدها…\n\nزين لشباب السلف ستدي…احضر ويخليك في حالك لنهاية المحاضره مايهمه شتسوي…\n\nبالتوفيق…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474772-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-p-gandhidasan/98188/25", "user": "Dyaa94", "ts": 1496935391000, "tid": 98188, "pn": 25}}]}', 1496935391000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_faddagh-me315', 'stk-m_faddagh', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98188", "n": "Dr. P. Gandhidasan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME315 term 162\n\nالدكتور يحضر كل يوم ولا مرة نسى يحضر\nيشرح من نوتات هو كتبها قبل 100 سنة وخطه مو واضح\n\nميزته الاولى انه يحل مسائل وااااجد ويحل اسئلة الهومورك وهذا اللي فادني شخصيا ، لكن ككونسبت فشرحه صفر على الشمال\nالميزة الثانية هي انه يلمح لبعض المسايل اللي تجي في المياجر\nطبعا ترم 162قرروا يحطون كونسبت بروبلمز في المياجر (MCQ) وكانت صعبة جدا بالنسبة للسكاشن الثانية اما سكشنه فكان يحدد لنا المهم في يوم الميجر في الكلاس وغالبها تجي بالميجر\n\nلا تحاول تساله لانك بتضيع وقت معاه ، انا ماادري هل هو مو فاهم او توصيله للمعلومة سيئ لكن ماراح تحصل جواب وافي كافي منه.\n\nتصحيحه عادي جدا، لكن في اسئلة الديريفيشن في المياجر لا تتركها فاضية، ألّف واكتب انتجريشن ومعادلات … لانه يعطيك اكثر من نص الدرجة اذا شاف جهدك في مثل هذه الاسئلة لاني اعتقد انه مو متمكن بالدرفيشن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480590-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-p-gandhidasan/98188/26", "user": "m_faddagh", "ts": 1505829411000, "tid": 98188, "pn": 26}}]}', 1505829411000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9084-me315', 'stk-user9084', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98193", "n": "Dr. Syed Zubair", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315\n\nTerm : 111\n\nالتحضير :\n\nكان يحضر بداية كل كلاس ولو جيت متأخر يحضرك اخر الكلاس بدون late ولاشئ\n\nطريقة الشرح :\n\nكان يشرح على سلايدات فيها أهم القوانين اللي في الكتاب وأسئله محلوله من نهاية كل شابتر\nيعني ينقي أهم الاسئله واللي تبين انها مهمه وتشرح الدرس كويس …\n\nيعني بالعربي سلايداته حلووووه وتفيدك 👍\n\nالكويزات :\n\nمتوسطة , ويبيلك تركيز بسيط لبعض النقاط \" لأنه يحاول يطلع اللي فاهم واللي نص ونص 🤠\n\nالمياجر:\n\nطبعا بالترم 111 ماكانت كومون الاختبارات فـ كانت متوسطة مايله الى السهوله\n\nالفاينلات :\n\nكان شوي صعيب \" عششان فقط الرسمات ماكنا حاسبين حسابه 😐\nرسمات تبع السرعه للمائع وغيره \"\n\nالقريد النهائي:\n\nA\n\nالصوت:\n\nماشوف فيها شئ 🙂\n\nإضافات :\n\nالدكتور فاهم بقوووه للماده لأن من يوم طلعت الهيت على الدنيا وهو يدرسها 😆\n\nفـ حاول تاخذ منه المعلومات قدر المستطاع 🙂\n\nولاتبخل على نفسك بالاوفيس اور رح له وأسأله , لأنه يحب اللي مجتهد ويبي يحصل المعلومه 👍\n\nمن ناحيه التصحيح فوق البطل صراحه تصحيحه زين بالحيل 🙂\n\nلأن لو أخطيت بأول السؤال مايروح يتابعك بالخطأ ويخصم عليك , يخصم عليك شئ بسيط 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1047191-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-zubair/98193/9", "user": "user9084", "ts": 1338246737000, "tid": 98193, "pn": 9}}]}', 1338246737000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_918-me315', 'stk-_918', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98193", "n": "Dr. Syed Zubair", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315 Term 112\n\nشرح عادي جدا … يقرا سلايدات … مرات يكتب قوانين مهمه ع السبوره\n\nكوزات صعبه صراحه\n\nتحضير يومي\n\nقريد نهائي : عادي جدا … يا دوب يعطيك حقك\n\nمدرس علاقته رسميه مع الطلاب بشكل ممل … ما عنده مشكله يخلص تشابتر كامل ب كلاسين\n\nشغل سريع سريع يقلب ب السلايدات\n\nالقريد النهائي : عطاني سي بلص … اعطيه سي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1048079-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-zubair/98193/13", "user": "_918", "ts": 1338384257000, "tid": 98193, "pn": 13}}]}', 1338384257000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a_student1-me315', 'stk-a_student1', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98193", "n": "Dr. Syed Zubair", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me 315\nالتحضير : أول ما يبدأ الكلاس يوميا ينادي على الأسماء لو تبي تمشي بعدها ما يقول لك شيء , و في اخر الكلاس يتجمعون عنده الطلاب المتأخرين و يحضرهم.\nطريقة الشرح : من السلايدات يشرح و يوضح على السبورة بعض النقاط\nالكويزات : تحتاج مذاكرة و مراجعة , صعيبة شوية\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي: عطاني c , و أعطيه +c\nالصوت: مهوب ذاك الزود صوته ضعيف الى متوسط\nإضافات :\nاللي أشوفه انه ما يهتم بالطالب ذاك الإهتمام , فهمت الله يحييك ما فهمت بسلامتك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1118064-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syed-zubair/98193/21", "user": "A_student1", "ts": 1353039849000, "tid": 98193, "pn": 21}}]}', 1353039849000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3804-me315', 'stk-user3804', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 315\n\nالتحضير :\n\nبداية كل كلاس و يدقق على التأخير\n\nطريقة الشرح :\n\nعنده سلايدات وطابعها على نوت,\n\nلكنها طالعة صغيرة و بعض الكلام مهوب واضح\n\nوبعض المعادلات مشكلتها تجيك مظللة فمع الطباعة السيئة تصير صعبة في القراءة\n\nميزته إنه مايشرح إلا اللي بيجيك في الاختبار, واذا فيه أشياء مهيب مهمة يقولك عنها\n\nأو يقولك تعاله في المكتب ويشرحها لك اذا كانت مرة صعبة\n\nالكويزات :\n\nسهلة…\nبعض الأحيان يخليها من الفيديو المطلوبة,\n\nالمياجر:\n\nكومون, بس تصحيحه جيد,\n\nمشكلته انه يبي يخلص التصحيح بسرعة. فتضطر تراجع الورقة,\n\nخصوصا لاصار مخلي طلاب يصححون…\n\nالفاينلات :\n\nكومون, والظاهر انه يخلي مجموعة من الطلاب يصححون معه عشان يخلصها بسرعة\n\nلكنه يسوي حركة حلوة قبل الفاينل وهي يعطيك درجتك المتوقعة و يعطيك في الفاينل افرج درجة مياجرك\n\nالقريد النهائي:\n\nوالله احترت…\n\nاذا انت انسان تبي تفهم المادة صح فهو بياخذ a+\nاذا انت تبي بس تاخذ الكورس وتخلص فأعطيه c+\nلأنك بتتعب مرة خصوصا لو صارت ماخذ انكليزي بعد…\n\nالصوت:\n\nيتكلم بالعربي أغلب الكلاس, و بلهجة عامية\nميزة كلاسه انه بعض الاحيان يصير ضحك ووناسة\n\nإضافات :\nبالنسبة للشغل معه و طريقة الهوموركات و البروجكتات:\n\nهو يقسم السكشن إلى مجموعات عمل, وخلاص من يومها الهوموركات و البروجتات تشتغلونها سوا\nوفيه بعد تلخيص الفيديو, وهو فيديوات لدكتور من جامعة بومبي يشرح فيها الهيت ترانسفير بشكل جيد جداً\nكل اللي تسويه هو انك تكتب ملخص عنها او انقلها زي ماهي\n\nلكنه في الأخير بياخذ هومورك ولا تلخيص واحد من القروب و يقيمكم عليه فلازم تكونون كلكم مسوينه…\n\nبالنسبة للبروجكتات فهو يقسمها إلى 2 او 3\n\nوصح انها تعب و قلق لكنها بتخليك تفهم المادة الصراحة…\n\nوبالنسبة للقروبات:\n\nكل طالب لازم يصير القائد لفترة معينة و عند انتهاء فترته لازم يعطي زي الملخص للي سويتوه في ذيك الفترة\nطبعا هو يقول لازم تجتمعون اسبوعيا عشان الهومورك و الفيديو واكتبوا وش صار في هذاك الاجتماع\n\nعموما تراك بتتعب معه و يمكن تكره عمرك, لكنك بتطلع فاهم المادة الصراحة,\n\nوبالمناسبة القريدات عنه ستاندرد مهيب أفرج…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p789644-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/3", "user": "user3804", "ts": 1297679979000, "tid": 98200, "pn": 3}}]}', 1297679979000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amat_24-me315', 'stk-amat_24', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me315 - semester102\n\nقبل التفكير في اخذ الكورس مع الدكتور بناء على المادة نفسها،، لازم تفكر فيه بناء على طريقته في الكلاسات\nعند الكتور نظام اسمه الclasswork،، فكر بجدية هل عندك استعداد تشتغل في قروبات ولا لا، اذا ما عندك استعداد اياك تاخذ معاه، وقالها اول السمستر اللي ما عنده استعداد يسوي دروب\n\nفي اول اسبوع يشرحلنا طريقته بشكل بسيط، الكلاس يوزعه على قروبات من 4 الى 5 طلاب في كل قروب،، الاختيار مو بيدك لكن بيد الدكتور، يوزع علينا اوراق فيها اسئلة عن شخصية الطالب وقريده في كورسات الهيت اللي اخذها قبل وبناء عليها يوزع القروبات\nطريقة جلوس الطلاب في الكلاس حسب القروب، كل قروب يكون دائرة يجلسو فيها الاعضاء (يعني تقريبا ما تقدر تتحكم بمكانك بالنسبة للي يحبو يجلسو قدام او ورى)\nالدكتور يعطي اسئلة عمل جماعي في اللكشر ويطلب من الطلاب يحلوها بجماعات يعني تتعاون مع اللي معاك وتحلو السؤال سوى، سؤالين بالكثير كل محاضرة واحيانا ولا سؤال لو كان في بداية شرح ثيوري جديد\nبالنسبة لشغلك مع القروب خارج الكلاس، حل الهوموورك يكون مع القروب يعني لازم تحلوه سوى في اجتماع او ما شابه\nنفس الشي بالنسبة للبروجكت، تجتمعو وتشتغلو عليه سوى\nفي نهاية السمستر كل قروب راح يكون عنده درجة كلاس وورك موحدة،، وكل طالب في القروب ياخذ درجته بناء على تقييم يوزعه الدكتور على اعضاء الفريق، بحيث انه اعلى واحد يكون عنده factor 1 ينضرب في درجة القروب، وكل طالب يكونه الفاكتر حقه اقل من 1 حسب التقييم وينضرب في الكلاس وورك حق المجموعة.\nبالنسبة للتقييم، يكون عندك 100 درجة توزعها بين كل عضو في المجموعة حسب ما يستحق ولها 5 معايير على ما اتذكر. يعني مثلا اذا شفت واحد ما يحضر اجتماعات الهومورك وما سوى شي في البروجكت بس قعد يتفرج، تقييمه ينزل والكلاس وورك حقه يكون اقل\n\nالتحضير : يومي، لكن الدكتور يغيب احيانا، اعتقد غاب 4 محاضرات في سمسترنا، احيانا يقول تعالوا في الليل عشان نلحق على المنهج (الحضور اختياري يعني ما عليه تحضير) ويعطي bonus للي يجي 0.2%، اذا جمعت بونسات يمكن تطلع بقريد افضل\n\nطريقة الشرح :الدكتور يحط النوتس او حسب ما يسميها الclass manual في الوب سيتي، لازم تطبعها وتجيبها معاك ولا ما تتحضر، الدكتور يعرضها كسلايدات على البروجكتر وتتبع معاه في النوتس اللي عندك وتعدل اذا شفته عدل شي او تضيف ملاحظاتك، الدكتور يركز جدا على الtheory يعني اشكال القرافات مثلا، شرحه واضح وضرب امثلة باشياء من الحياة واحيانا تقلب وناسة، النوتس مافيها امثلة محلولة ، اذا فيه سؤال يطلب من القروب يحلوه سوى في الكلاس\n\nالكويزات : فيها تركيز غير طبيعي على الtheory وطريقة اشتقاق المعادلات، الاشتقاق كله موجود في النوتس طبعا\nالدكتور يحط لكشرز فديو على الوبسيتي لدكتور هندي يشرح، احيانا الكويز يكون على شرحه او على تصنيفه لمسالة معينة\nبالنسبة للفديو، لا باس به، يساعدك اذا حسيت انك مضيع في نقطة معينة\n\nالمياجر:مو صعبة ، بعض المياجر يصححها مع طلاب ويحط السلوشن على الوب سيتي على اساس انك تراجعها، لازم تراجعوها، لانه اللي يصحح مرات يطفش ويشوفك غلطان في نقطة يقوم يعطيك على السؤال بكبره صفر، لكن الدكتور نفسه تصحيحه ممتاز يركز على الخطوات اكثر من الجواب النهائي، يعطيك حقك اذا راجعت معاه بشرط انك تكون فعلا انظلمت علشان ما يهزئك،، اتذكر في ميجر ون زدت 25% بعد المراجعة بسبب اخطاء في التصحيح\n\nالفاينلات : كان 50% مسائل كاملة تطبيقية و50% اختيارات او اشتقاق او مسائل بسيطة،، ال50 الثانية فيها تركيز شديد على الtheory\n\nالقريد النهائي:A\n\nالصوت: واضح\n\nإضافات : قبل ما تاخذ الكورس اسال نفسك ،، هل عندك استعداد تشتغل في قروبات ولا لا\nهذي تسبب مشكلة للي ساكنين برا الجامعة وصعب عليهم يجو للاجتماع اذا اختاروه الشباب في الجامعة او للي ساكنين بعيد او دايما يطلعو الرياض في الويك اند ، مع انه الدكتور يحاول قدر المستطاع يحط اللي ساكنين جوا في مع بعض واللي ساكنين برا مع بعض\n\nميزة القروب وورك انه يجبرك تذاكر المادة اول باول مع القروب\nالنوتس حقت الدكتور ممتازة وممكن تغنيك عن الكتاب، تقسيم الشباتر فيها مختلف تقريبا عن الكتاب\n\nنصيحة للي ياخذو معاه الكورس: اشتغلو على البروجكت من بدري، البروجكت موجود في النوتس وتقدر تبدا فيه في اي وقت،، ونصيحتي سووه اول ما تخلصو الشباتر المتعلقة بالبروجكت يعني لا تاجلو الشغل لآخر اسبوع قبل الdead line لانه يبغاله شغل في اللاب وغالبا حتلاقوه زحمة بسبب القروبات الثانية من السكشنين اللي يدرسهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p856349-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/5", "user": "amat_24", "ts": 1308600603000, "tid": 98200, "pn": 5}}]}', 1308600603000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_pirate-me315', 'stk-_pirate', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر هذا 121 احد السكاشن (15) واحد ما بين A و B+ و B وعدد الطلاب 26\n\nوالسكشن الثاني عددهم 32 منهم 16 واحد A , B+,B\n\nبختصار الدكتور افضل من يشرح me 315 في العالم عنده مبادىء يطلع الطالب واثق بنفسه ويعطيه بروجكتات تخليه يطور من نفسه وتعرف طلابنا ما يحبون المهام فيسبونه\n\nواما اخلاقه صراحه ما يزعل الا على اللي مبزوطين شديد معهم بس والكلام السيءاللي يقال عنه اغلبه كذب\n\nبختصار ابو شايع بطل بهذه الصفات :\n(شرح ونوت وقريد وضحك ومتعه فالشرح ويرفع مهاراتك لكن شديد على الكسلانين يحب اللي يحل الامثله ويحظر))", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1170177-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/13", "user": "_pirate", "ts": 1359224844000, "tid": 98200, "pn": 13}}]}', 1359224844000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s_h_a_d_o_w-me315', 'stk-s_h_a_d_o_w', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315 - Term 122\n\nبنود التقييم :\n\nالتحضير : يحضر يوميا في آخر المحاضرة. يوجد خصم على الغياب بس في بونس لو ماغبت ولا محاضرة\n\nطريقة الشرح :زي ماقالو الشباب، يقسمنا قروبات في أول الترم و يشرح من سلايدات بطريقة ما تمل منها و يطلب من القروبات حل بعض الأمثلة علشان تثبت المعلومة و يساعدك لو ماعرفت كيف تحلها\n\nالكويزات :أعطانا على ما أتذكر 2 أو 3 كلاس تستست متوسطو الى سهلة\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي:A+\n\nالصوت:ممتاز ويشرح بالعربي معظم الأحيان ولكن يركز على المصطلحات و التعريفات الي لازم تعرفها بالانجليزي\n\nإضافات : المادة بشكل عام صعبة وتحتاج جهد والاستاذ بالرغم من طلباته الكثير خصوصا في مسألة القروبات الا انه راح يسهل عليك الفهم و المذاكرة وتكون مستعد للمياجر و الفاينل بإذن الله.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1248166-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/16", "user": "S_H_A_D_O_W", "ts": 1374652265000, "tid": 98200, "pn": 16}}]}', 1374652265000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10096-me315', 'stk-user10096', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98200", "n": "Dr. Mohammad Al-Qahtani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سميستر ١٧١،\nME315\nطريقة الدكتور مختلفة وممتازة هذا السميستر\nكل اسبوع ينزل ١٠ فيديوات تقريبا تلخص كل واحد منهم في ورقة A4 والكلاس غالبا يكون حل مسائل اضافية ومرات يعطيك bonus quizzes، عطانا مرة كلاس بالليل اي احد جا عطاه bonus …مفيدة جدا لك اذا جبت العيد بالميجر مثلا.\n\nانا بتخرج قريب واقولك ان الدكتور محمد من افضل الدكاترة اللي درسوني تعاملا و شرحا واذا شاف طالب ضعيف يركز عليه عشان يشد حيله\nوتحسه يبي يعطيك A+ وحريص على ذلك .\nويستانس اذا متوسط درجات طلابه كان مرتفع ويشجعهم بbonus زيادة\n\nعموما انا اللي اسعفني ان هالسميستر فاضي نوعا ما عندي الا ١٣ ساعة … فكان عندي الوقت اني اسوي الفيديوات واستفيد منها وسهلت المادة علي جدا\n\nالقريد النهائي : للحين لكن متفائل خير\nوالمادة عنده ستاندرد\nانصح بالدكتور", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1483743-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-al-qahtani/98200/34", "user": "user10096", "ts": 1511388918000, "tid": 98200, "pn": 34}}]}', 1511388918000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-salty-me315', 'stk-salty', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98202", "n": "Dr. Rashed Ben Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315\nTerm 152\nانا ادرس عنده حاليا\n\nالتحضير :\nبعد بداية الكلاس بخمس دقائق واحيان في الاخير.\nطريقة الشرح :\nيشرح على السلايدات مع حل بعض الامثلة و توزيع اوراق لأسئلة مهمة ويحلها في الكلاس\n(اقدر اقول ان الدكتور يسوّي اللي عليه ويحاول يوصّل المعلومة قد ما يقدر لكنه مو خورافي … لازم تدرس بالبيت)\nالكويزات :\nكويز سهل وكويز عادي وكويز صعب (متنوّعه)… احيان من الهوموورك بس يغيّر عليه شوي\nالمياجر:\nتصحيحه عادي و منصف في المياجر و الاختبارات … وتقدر تراجعه بكل صدر رحب (متعاون)\nالفاينلات : ----\nالقريد النهائي:\nاعطي الدكتور B\nالصوت:\nواضح جدا ومفهوم (عربي وانقلش)\nإضافات :\nالتعليقات اللي قبلي ما اعتقد كانت منصفه\nوممكن السبب ان الدكتور حاليا يدرّس me315\nع العموم الدكتور كويّس الصراحة … يشرح كويس و متعاون مع الطلاب في مواعيد الكويزات وتسليم الواجبات\nلكن الماده ماهي سهله والطلاب ما يبغو يذاكرو في البيت (هذي حقيقة للاسف)\n\nبالنسبة للقريدات … ما ادري كيف وضعه في القريدات النهائية وكم الافرج عنده … لكن الله يستر ان شاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1446489-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashed-ben-mansour/98202/6", "user": "Salty", "ts": 1460469177000, "tid": 98202, "pn": 6}}]}', 1460469177000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-shazom-me315', 'stk-shazom', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98202", "n": "Dr. Rashed Ben Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315. TERM 161\nالتحضير :\n\nيحضر كل يوم بداية الكلاس او نهايته, الرجل بالمناسبة غالبا يتاخر على الاقل 5 دقائق عن بداية الكلاس.\nطريقة الشرح :\nيشرح من سلايدات, ويحل مسائل على السبورة. ممكن يشرح بعض الاشياء على السبورة احيانا\nالكويزات :\nحوالي 6 كويزات, ياخذ احسن اربعة منها, لو تحل اول مثال في التشابتر بس راح تجاوب على كوزاته بسهولة.\nالمياجر: كومن\nالفاينل :كومن\nالقريد النهائي: B\nالصوت: واضح بس لو تكلم عربي ما بتفهمه. اعتقد جزائري.\nإضافات :\n\nمن ناحية الشرح الدكتور ممتاز ولكنه يركز على التفاصيل مره غير المهمه ,ويشرح المنهج من غير اي اعتبار للسلبس, راح تسمع اشياء كثيرة وتتقروش فيها وتكتشف في الاخير انها مش معك في الخطة اساسا!! هنا ننصح بالبحث عن السيلابس حق القحطاني لانه مفصل وموجود في الدرايف, تستطيع ببساطة ان تعمل سويتش اوف اذا دخل يشرح في السكاشن المحذوفة.\n\nمن ناحية التصحيح الرجل دقيق, يحب يكون الحل نموذجي, يعطيك فوق حقك بحاجة بسيطة ومتعاون في اثناء الاختبارات, يعني ممكن تساله ويعطيك هنت يحل لك السؤال! صارت معي مرتين شخصيا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466924-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashed-ben-mansour/98202/7", "user": "shazom", "ts": 1485271153000, "tid": 98202, "pn": 7}}]}', 1485271153000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-madridista-me315', 'stk-madridista', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98202", "n": "Dr. Rashed Ben Mansour", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171- ME315\n\nالدكتور نظامه \" خل نسلك لبعض لين الترم يخلص 🙂 \"\nتصحيحه مرات حلو ومرات سيء، الاغلاط اللي يكون وراها كونسبت يخسفك عليها “حرفياً”\nمايحاسب عالتأخير ، ولا على الغياب (اهم شيء لا توصل للDN) … كويزاته سهله كلها من الهوموورك او امثلة الكتاب\nالبروجكت ككل عليه 10% … 7 درجات على الريبورت، و3 درجات على البرزنتيشن.\nشرحه بصراحة اشوفه ممل، كنت اجي الكلاس اقعد عالجوال… ووقت المياجر اذاكر من مقاطع القحطاني\nما اشوف انه دكتور سيئ ولا دكتور كويس… عادي يعني\n\nبالتوفيق للجميع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485818-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashed-ben-mansour/98202/9", "user": "Madridista", "ts": 1515503067000, "tid": 98202, "pn": 9}}]}', 1515503067000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-menoo-me315', 'stk-menoo', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f98205", "n": "Dr. Mostafa H. Sharqawy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me315 - Term 131\n\nالتحضير : يومياً نهايه الكلاس\nطريقة الشرح : سلايدات كونسبت ، والدرفيشن ع السبوره ، ويحل مسائل ع السبوره وباستخدام الاي اي اس …\nالدكتور شريح ماعليه كلام …\nالكويزات : متوسطه إلى سهلة\nالبروجكت : حرررررررريقه ، كل السكشن بين الـ 40 والـ 50 ،، من 100\nالمياجر: كومون\nالفاينلات : كومون\nالصوت: واضح ومسموع\nالقريد النهائي: B\nاضافات : الدكتور ماشي ع نظام الثيرمو ان توزيع القريدز ستاندرد ،، وهالشي أبداً ما ينفع مع ماده مثل الهيت\nخصوصاً إنه ما قصر فينا في البروجكت وخسفنا خسف ،،\n\nفي نهاية المطاف ماحد طلع عنده من الكورس بـ A+\nLetter Grade A+ A B+ B C+ C D+ D F\nRange > 92 85 – 92 80 – 85 70 – 80 65 – 70 60 – 65 50 – 60 40 – 50 < 40\n\nانا ما انكر ان الدكتور شريح ، واني طلعت فاهم الماده 99% ، ولكن ما اشوف في قريداته عدل بالنسبه لباقي السكاشن ،،\n\nفبالعربي إن كنت تبي قريد انحششش ، واذا كنت تبي تفهم وتقدر تستغني عن القريد نزل معاه …\n\nوسلامتكم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1315419-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mostafa-h-sharqawy/98205/16", "user": "Menoo", "ts": 1388924841000, "tid": 98205, "pn": 16}}]}', 1388924841000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-me315', 'stk-abdullatif1994', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f103287", "n": "Dr. Atia Khalifa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME315 Term151\nالتحضير : يمرر ورقة ع الطلاب ويحضروا … ولك 8 غيابات Free وبعدها Dn … بالاحرى ماعنده خصم ع الغيابات\nطريقة الشرح : يشرح على السلايدات وشرحه مثل الكتاب … ( بالنسبة لي الكتاب يغنيني عن شرحه )\nالكويزات : 3 كويزات … اول 2 كانو صعبين والاخير متوسط … عليهم 5 درجات لكل واحد\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي:A\nالصوت: واضح …\nإضافات : الصراحه مانصح فيه … تصحيحه سيء … ويمشي بالملي … ومادته ستاندرد … يعني لاتقول بيخسف الكل وفي الاخير الافرج نازل …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449915-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/atia-khalifa/103287/28", "user": "Abdullatif1994", "ts": 1463846260000, "tid": 103287, "pn": 28}}]}', 1463846260000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-illusions-me315', 'stk-illusions', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f103290", "n": "Dr. Abdulrahman Al-Murbati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 315\nTERM 191\n\nالتحضير : كل يوم , وكل يوم وقت , عادي تدخل عقب دقيقتين تلقاه محضر وعادي تدخل اليوم الثاني تلقاه يحضر عقب ما يخلص الوقت, ما ينشب مره على التأخير الا اذا مصختها. الخصم اخبر انه مره واحد سأله قال انتم السمستر هذا ممصخينها فبخصم على الغيابات.\n\nطريقة الشرح : شرييييييييييييييح , من سلايداته ويحل المسائل الي فيها ويربط بالواقع كثير, اتوقع انه من افضل ثلاثة درسوني بالجامعة ماشاءالله عليه.\n\nالكويزات : عطانا الظاهر 7 كويزات واخذ اعلى خمسة , كنت اشوف الكويزات بوقتها صعبة بس اذا ذاكرت للميجر ورجعت عليهم من جديد اشوفهم قريبات مره لمستوى الاسئلة الي بالسلايدات وكثير منها اذا فتحت الاولد اقزام عقب لقيتها منسوخة بالارقام 😅\n\nالمياجر: كومن , وطريقة المياجر للامانة ما تعطيه فرصة يدفك اصلا فبيعطيك حقك بالضبط.\n\nالفاينلات : كومن ونفس المياجر التصحيح.\n\nالقريد النهائي: A للدكتور , احس من اكثر المواد الي فهمتها بالجامعة الله يجزاه خير.\n\nالصوت: عالي وواضح\n\nإضافات : للامانة ما طلعت بقريد عالي معاه فأشوف انه يعطيك حقك بدون زيادة ولا نقصان بالقريد , الميجر الاول كنت تحت الافرج , الثاني فوقه , الفاينل اتوقع اني حول الافرج , انا الصدق كنت منضغط شوي هالسمستر فما اذاكر اول بأول بس كنت اطلع من الكلاس وانا احس اني فاهم فالدكتور انصح فيه. البروجكت حقه سهالات واخبر انه خمس قروبات بالكلاس كل قروب 4 اشخاص عطى قروبين كامل من 8 وقروبين حول 6 وقروب اقل منها الظاهر.\nمب تقليدي الدكتور, يعني عادي يتكلم عن صعوبة شغلة ولا انها معقدة وكذا ويجي واحد من الطلاب ويقط كلمة فيضحك الدكتور مع الكلاس فالوضع حليل بكلاسه شوي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518533-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-murbati/103290/12", "user": "ILLUSIONS", "ts": 1577827103000, "tid": 103290, "pn": 12}}]}', 1577827103000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-me315', 'stk-khdsa2022', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f103290", "n": "Dr. Abdulrahman Al-Murbati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : عبدالرحمن المرباطي\nby whats app\nالمادة: ME 315\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :متساهل في التأخير شديد في التحضير\nطريقة الشرح :من السلايدات ويكتب على السبورة شرحه واااضح ومتجاوب مع كل الأسئلة\n\nالكويزات : كانت اسئلة اولد اقزام الصراحة ومرات يسهل لكن الأغلب تكون لازم تجيه مذاكر مذاكرة ميجر.\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي:A+\n\nالصوت:واضح\n\nإضافات : اكثر مادة في التخصص حبيتها بسببه الله يسعده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518752-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-murbati/103290/13", "user": "Khdsa2022", "ts": 1578209451000, "tid": 103290, "pn": 13}}]}', 1578209451000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed427-me315', 'stk-mohammed427', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f103290", "n": "Dr. Abdulrahman Al-Murbati", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : ME-315 202\n\nالتحضير : تحضير تلقائي من البلاك بورد\nطريقة الشرح : عنده سلايدات خاصه فيه يشرحه فيها وفيها عدد من المسائل، يركز على الكونسبت و يحاول يوصله لك باكثر من طريقة، ويربطه بالحياة الواقعية.\nالكويزات : عطانا 8 كوزات اغلبها يتكون من سؤالين اختياري وسؤال حل، الكويزات مستواها من سهل الى متوسط.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: الله يعيطه العافية والله ماقصرت معانا، اذكره في الفيانل قال الدرجة بتكون مع العيد وبتكون هي عيديتكم وصدق والله ، A+.\n\nإضافات : احيانا بين كل فترة وفترة يسوي كلاس اكتفيتي بحيث يقسم الشعبة لقروبات ويعطيهم مسائل للتدريب ويناقش الحل نهاية الكلاس.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530942-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulrahman-al-murbati/103290/18", "user": "Mohammed427", "ts": 1626659882000, "tid": 103290, "pn": 18}}]}', 1626659882000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ksa1990-me315', 'stk-ksa1990', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f118632", "n": "Dr. Saad Mansoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term:172\nME315\n\nالتحضير : أول ما يبدا الكلاس على طول يحضر تتأخر يعطيك ليت\nطريقة الشرح : يكتب نوت على السبورة والنوت ممتازة جدا يبدأ بشرح الكونسبت بعدين يحل عليها مسائل كثير- لكن للأمانه ما اقدر اقيم الشرح لاني كنت اذاكر المادة من قناة الدكتور محمد القحطاني باليوتيوب فما كنت اركز مع الدكتور بالكلاس.\nالكويزات : الكوزات سهله جدااااا وهذا الي يميز الدكتور ان تقدر تاخذ فل مارك بالكلاس وورك بسهولة لأن الكوزات كانت سهله\nتكون عبارة عن سؤال واحد اختيارات وغالبا وقت الكويز 5 او 10 دقايق بس وغالبا ينحل بقانون واحد او قانونين يكون سؤال بسيط\nعطانا 6 كوزات واخذ افضل 3\nالمياجر: ما كنت اراجعها معاه فما اقدر احكم\nالفاينلات : عطانا الدرجه على طول\nالقريد النهائي: A\nالصوت: واضح جدا\nإضافات : عطانا بروجيكت على المات لاب مجموعات كل 4 مع بعض اذا واحد من التيم يعرف يبرمج مات لاب فالبروجيكت كان مره سهل\nبشكل عام الدكتور ممتاز لكن يعيبه التحضير خصوصا بهذي المادة لأنها مشروحه شرح خورافي باليوتيوب فلو حصلت دكتور ما يحضر وذاكرتها سلف ستادي بيكون اريح وافضل بكثير\nاخر نقطة توزيع المادة كان ستاندر\nA 90-100+\nA 83-90\nB 77-83+\nB 72-77\nC 65-72+\nC 58-65\nD 53-58+\nD 45-53\n(+-)2 على حسب الأفرج\n+ الدكتور عطاني اب قريد وباقيلي اكثر من درجة على القريد الي بعده يمكن لأن ما عندي ولا تأخير أو غياب 🙂\nتوزيع المادة:\nExam 1: 20%\nExam 2: 20%\nQuizzes: 10%\nDesign project: 10%\nHomework: 10%\nFinal Exam (Comprehensive): 30%", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501877-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/saad-mansoor/118632/26", "user": "ksa1990", "ts": 1541356335000, "tid": 118632, "pn": 26}}]}', 1541356335000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-owheading-me315', 'stk-owheading', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f118637", "n": "Dr. Obaidallah Munteshari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME315- TERM 191\n\nالتحضير :\nبالأسماء وأحيانًا ما يحضر، الغياب ماعليه خصم ولكن! الي يغيب كثير ما يساعده في القريد فلا تغيب أحسن، لأن بياخذ عنك انطباع المهمل\nطريقة الشرح :\nممتاز جدًا، من السلايدات وع السبورة يكتب بعد، ويحل مسائل كثير، ويعطي كلاس ورك يخليك تتمرن، من الآخرر رهيييب\nالكويزات :\nيختبرك يمكن 7 كوزات وياخذ أفضل 5، الكوزات من الواجبات غالبًا ونفس المستوى، تقريبًا في الجيب\nالمياجر والفاينلات: common وتصحيحه ممتاز\nالقريد النهائي: A++++++++++\nالصوت: واضح\nإضافات : الدكتور رائع جدًا من كل النواحي، انصح به بشدة، شرح وتصحيح وتعاون وأخلاق، مفصل ع الطالب الجامعي تفصيل، ويساعد في القريد لو شافك مهتم وتستاهل، الله يعطيه ألف عافية دكتور رائع بجد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522446-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/obaidallah-munteshari/118637/8", "user": "OWHEADING", "ts": 1590690422000, "tid": 118637, "pn": 8}}]}', 1590690422000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wil.e-me315', 'stk-wil.e', 'ME 315', 'doc', '{"docs": [{"id": "stk-dr-f118637", "n": "Dr. Obaidallah Munteshari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME315 - Term 202\n\nبنود التقييم :\n\nأول شي صلّ على محمد،\n\nالتحضير : كان يحضر بالتيمز بعدين صار التحضير باستخدام اسيسمنت (اختبار عن اللي شرحه الدكتور، ما عليه اي درجات بس مفيد جدا للمذاكرة)، و في الأخير صار الموضوع اختياري بسبب التقيم وظروف رمضان\n\nطريقة الشرح : سلايداته الخاصة ويحل أمثلة ويشرح لين تفهم، يسمح لك تقاطعه اذا عندك شي تبي تسأل عنه، ويحب تفاعل الطلاب معه ويزعل اذا محد سأل فلا تزعلون الدكتور 🤠\n\nالكويزات : أحيان خيارات كونسبت و مسائل، واحيان خيارات كونسبت ومسألة حلها يدوي وترفعها له، وصراحة كلها سهلة وفي المتناول\n\nالمياجر: صراحة كان ميد وكان صلخ شوي خصوصا في جهة الحل اليدوي، جاب سؤالين فكرة الحل فيهم pure math وورطني، لكن تصحيح الدكتور ما شاء الله لا يعلى ليه وساعدنا فيه\n\nالفاينلات : كان نار وتوقيته صعب، العيال كانو طالعين من مشين 2 من اليوم اللي قبله وجاي في نهار رمضان، وكان اخر اختبار فلكم أن تتخيلوا حجم الصعوبة، لكن برضوا الدكتور ما قصر وساعدنا باللي يقدر عليه جزاه الله خير\n\nالتصحيح : حلو مرة ويعطيك حقك وزيادة بعد، اذا عندك اي مشكلة يمديك تناقشه وهو يرحب بالطلاب\n\nالقريد النهائي: A+++++++\n\nالصوت: واضح والشرح مسجل لو تبي، واحد من الشباب سوا قناة تيليقرام فيها شرح الدكتور بالكامل وطبعا فيه اشياء ما غطيناها بسبب ضيق الوقت،\nME315 Munteshari Videos\n\nإضافات : اذا حصل لك مكان نصيحة لا تفوتة أبدا، وشكرا 👋", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529931-me315", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/obaidallah-munteshari/118637/10", "user": "wil.e", "ts": 1620554362000, "tid": 118637, "pn": 10}}]}', 1620554362000, 1794826870, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
